import itertools
def has_short_cycle():
    n = 19
    adj = {i: set() for i in range(n)}
    steps = [1,6]
    for i in range(n):
        for s in steps:
            adj[i].add((i + s) % n)
            adj[i].add((i - s) % n)
    # now compute girth
    def bfs_girth(start):
        dist = [-1] * n
        dist[start] = 0
        parent = [-1] * n
        q = [start]
        min_cycle = float('inf')
        for u in q:
            for v in adj[u]:
                if dist[v] == -1:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    q.append(v)
                elif v != parent[u]:
                    cycle = dist[u] + dist[v] + 1
                    if cycle < min_cycle:
                        min_cycle = cycle
        return min_cycle
    girth = min(bfs_girth(i) for i in range(n))
    return girth, 38  # also num edges

